#define main v30_unused_main
#include "bdr_v30_ticketed_pipeline.cpp"
#undef main
#include <sqlite3.h>
#include <lmdb.h>
#include <leveldb/db.h>
#include <leveldb/write_batch.h>
#include <rocksdb/db.h>
#include <rocksdb/write_batch.h>

struct MR{std::string engine;int writers;int window;double ops;uint64_t errors;};
static std::atomic<int> gnext;

template<class F> static double timed(F&&f){auto a=Clock::now();f();return std::chrono::duration<double>(Clock::now()-a).count();}

static MR run_bdr(int total,int writers,int window){std::filesystem::remove("v32.bdr");TicketWal wal("v32.bdr",(size_t)total*96+4096,512);gnext=0;double sec=timed([&]{std::vector<std::thread>ts;for(int x=0;x<writers;++x)ts.emplace_back([&]{uint64_t last=0;int pending=0;for(;;){int i=gnext.fetch_add(1);if(i>=total)break;last=wal.submit(K(i),V(i));if(++pending>=window){wal.wait(last);pending=0;}}if(pending)wal.wait(last);});for(auto&t:ts)t.join();});auto r=recover("v32.bdr",total);uint64_t e=r.bad+r.missing+r.dup+(r.good!=(size_t)total)+(r.last!=(uint64_t)total);return{"BDR-v32",writers,window,total/sec,e};}

static void sqlite_exec_retry(sqlite3*d,const char*s){for(;;){int rc=sqlite3_exec(d,s,nullptr,nullptr,nullptr);if(rc==SQLITE_OK)return;if(rc!=SQLITE_BUSY&&rc!=SQLITE_LOCKED)throw std::runtime_error("sqlite exec");std::this_thread::yield();}}
static MR run_sqlite(int total,int writers,int window){std::filesystem::remove("v32.sqlite");sqlite3*d=nullptr;sqlite3_open("v32.sqlite",&d);sqlite3_busy_timeout(d,30000);sqlite3_exec(d,"PRAGMA journal_mode=WAL;PRAGMA synchronous=FULL;CREATE TABLE kv(k TEXT PRIMARY KEY,v TEXT);",0,0,0);sqlite3_close(d);gnext=0;std::atomic<uint64_t>err{0};double sec=timed([&]{std::vector<std::thread>ts;for(int x=0;x<writers;++x)ts.emplace_back([&]{sqlite3*c=nullptr;sqlite3_open("v32.sqlite",&c);sqlite3_busy_timeout(c,30000);sqlite3_exec(c,"PRAGMA journal_mode=WAL;PRAGMA synchronous=FULL;",0,0,0);sqlite3_stmt*s=nullptr;sqlite3_prepare_v2(c,"INSERT INTO kv VALUES(?,?)",-1,&s,0);for(;;){std::vector<int>ids;ids.reserve(window);for(int j=0;j<window;++j){int i=gnext.fetch_add(1);if(i>=total)break;ids.push_back(i);}if(ids.empty())break;sqlite_exec_retry(c,"BEGIN IMMEDIATE");for(int i:ids){auto k=K(i),v=V(i);sqlite3_bind_text(s,1,k.c_str(),-1,SQLITE_TRANSIENT);sqlite3_bind_text(s,2,v.c_str(),-1,SQLITE_TRANSIENT);if(sqlite3_step(s)!=SQLITE_DONE)err++;sqlite3_reset(s);sqlite3_clear_bindings(s);}sqlite_exec_retry(c,"COMMIT");}sqlite3_finalize(s);sqlite3_close(c);});for(auto&t:ts)t.join();});sqlite3_open("v32.sqlite",&d);sqlite3_stmt*s=nullptr;sqlite3_prepare_v2(d,"SELECT v FROM kv WHERE k=?",-1,&s,0);for(int i=0;i<total;++i){auto k=K(i);sqlite3_bind_text(s,1,k.c_str(),-1,SQLITE_TRANSIENT);if(sqlite3_step(s)!=SQLITE_ROW||std::string((const char*)sqlite3_column_text(s,0))!=V(i))err++;sqlite3_reset(s);sqlite3_clear_bindings(s);}sqlite3_finalize(s);sqlite3_close(d);return{"SQLite",writers,window,total/sec,err.load()};}

static MR run_lmdb(int total,int writers,int window){std::filesystem::remove_all("v32.lmdb");std::filesystem::create_directory("v32.lmdb");MDB_env*e=nullptr;MDB_txn*t=nullptr;MDB_dbi db=0;mdb_env_create(&e);mdb_env_set_mapsize(e,1ull<<30);mdb_env_open(e,"v32.lmdb",0,0644);mdb_txn_begin(e,nullptr,0,&t);mdb_dbi_open(t,nullptr,MDB_CREATE,&db);mdb_txn_commit(t);gnext=0;std::atomic<uint64_t>err{0};double sec=timed([&]{std::vector<std::thread>ts;for(int x=0;x<writers;++x)ts.emplace_back([&]{for(;;){std::vector<int>ids;ids.reserve(window);for(int j=0;j<window;++j){int i=gnext.fetch_add(1);if(i>=total)break;ids.push_back(i);}if(ids.empty())break;MDB_txn*tx=nullptr;if(mdb_txn_begin(e,nullptr,0,&tx)){err++;break;}for(int i:ids){auto ks=K(i),vs=V(i);MDB_val k{ks.size(),(void*)ks.data()},v{vs.size(),(void*)vs.data()};if(mdb_put(tx,db,&k,&v,0))err++;}if(mdb_txn_commit(tx))err++;}});for(auto&th:ts)th.join();});mdb_txn_begin(e,nullptr,MDB_RDONLY,&t);for(int i=0;i<total;++i){auto ks=K(i);MDB_val k{ks.size(),(void*)ks.data()},v{};if(mdb_get(t,db,&k,&v)||std::string((char*)v.mv_data,v.mv_size)!=V(i))err++;}mdb_txn_abort(t);mdb_dbi_close(e,db);mdb_env_close(e);return{"LMDB",writers,window,total/sec,err.load()};}

static MR run_level(int total,int writers,int window){std::filesystem::remove_all("v32.level");leveldb::DB*d=nullptr;leveldb::Options o;o.create_if_missing=true;if(!leveldb::DB::Open(o,"v32.level",&d).ok())throw std::runtime_error("level open");leveldb::WriteOptions wo;wo.sync=true;gnext=0;std::atomic<uint64_t>err{0};double sec=timed([&]{std::vector<std::thread>ts;for(int x=0;x<writers;++x)ts.emplace_back([&]{for(;;){leveldb::WriteBatch b;int n=0;for(;n<window;++n){int i=gnext.fetch_add(1);if(i>=total)break;b.Put(K(i),V(i));}if(!n)break;if(!d->Write(wo,&b).ok())err++;}});for(auto&th:ts)th.join();});leveldb::ReadOptions ro;for(int i=0;i<total;++i){std::string v;if(!d->Get(ro,K(i),&v).ok()||v!=V(i))err++;}delete d;return{"LevelDB",writers,window,total/sec,err.load()};}

static MR run_rocks(int total,int writers,int window){std::filesystem::remove_all("v32.rocks");rocksdb::DB*d=nullptr;rocksdb::Options o;o.create_if_missing=true;if(!rocksdb::DB::Open(o,"v32.rocks",&d).ok())throw std::runtime_error("rocks open");rocksdb::WriteOptions wo;wo.sync=true;gnext=0;std::atomic<uint64_t>err{0};double sec=timed([&]{std::vector<std::thread>ts;for(int x=0;x<writers;++x)ts.emplace_back([&]{for(;;){rocksdb::WriteBatch b;int n=0;for(;n<window;++n){int i=gnext.fetch_add(1);if(i>=total)break;b.Put(K(i),V(i));}if(!n)break;if(!d->Write(wo,&b).ok())err++;}});for(auto&th:ts)th.join();});rocksdb::ReadOptions ro;for(int i=0;i<total;++i){std::string v;if(!d->Get(ro,K(i),&v).ok()||v!=V(i))err++;}delete d;return{"RocksDB",writers,window,total/sec,err.load()};}

int main(int argc,char**argv){int total=argc>1?std::stoi(argv[1]):50000;int window=argc>2?std::stoi(argv[2]):128;std::cout<<"engine,writers,window,total,throughput_ops_s,errors\n";for(int writers:{1,4,8,16}){for(auto&r:{run_bdr(total,writers,window),run_sqlite(total,writers,window),run_lmdb(total,writers,window),run_level(total,writers,window),run_rocks(total,writers,window)}){std::cout<<r.engine<<','<<r.writers<<','<<r.window<<','<<total<<','<<r.ops<<','<<r.errors<<"\n";if(r.errors)return 2;}}}
